code_test:
g = {"a": ["b", "c"], "b": ["d"], "c": ["d"], "d": []}
assert toposort(g) == ["a", "b", "c", "d"], toposort(g)
# deterministic lexicographic tie-break among ready nodes
g2 = {"z": ["m"], "a": ["m"], "m": []}
assert toposort(g2) == ["a", "z", "m"], toposort(g2)
# cycle -> ValueError
try:
    toposort({"a": ["b"], "b": ["a"]})
    raise SystemExit("should have raised on cycle")
except ValueError:
    pass
assert toposort({"solo": []}) == ["solo"]
print("ok")
